-- Hot Air Balloon — pixel-art sprites in gfx/, generated by gfx/gen_sprites.py
--
-- Rules: steer the balloon with the joystick or by dragging the touch.
-- Each successful blow stokes the flame and adds fuel (NewRepetition
-- pulses at blow END, like in soccer). Fuel drains constantly and
-- maneuvering drains it faster. Hitting an obstacle costs fuel. When the
-- fuel runs out the balloon falls and resets.
-- The ground (and the obstacles on it) scroll leftward at DRIFT_SPEED:
-- the balloon's world position (ground offset plus its screen offset from
-- the start) is the flown distance, and it earns coins (one per
-- DIST_PER_COIN px). Coins and upgrades are persisted in the game's Prefs
-- namespace and bought in progressionMenu.lua.
--
-- init.lua runs once at game start (gameLua.cpp initGames_lua); mainGame.lua
-- runs every frame in every blow phase and keeps the state below.

function rgb(r, g, b)
  return ((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3)
end

-- 565 colors
COL_FUEL_OK  = rgb(0, 170, 90)
COL_FUEL_LOW = rgb(220, 40, 40)
COL_WHITE    = 0xFFFF
COL_BLACK    = 0x0000

-- Playfield (320x240 screen; the firmware status strip owns y 0..19 and
-- the bottom bars y >= 190, so game content lives between them).
PLAY_TOP    = 22
PLAY_BOTTOM = 188
GROUND_Y    = PLAY_BOTTOM - 23  -- top of the grass strip drawn by gfx/sky.bmp

-- Sprites: 16-bit RGB565 BMPs, pink is the transparent mask colour.
MASK        = 0xF81F
SBackground = LoadSprite("gfx/sky.bmp")
BalloonSkin = {
  LoadSprite("gfx/balloon.bmp", 0, MASK),
  LoadSprite("gfx/balloon_blue.bmp", 0, MASK),
  LoadSprite("gfx/balloon_green.bmp", 0, MASK),
  LoadSprite("gfx/balloon_gold.bmp", 0, MASK),
}
SBalloonDead = LoadSprite("gfx/balloon_dead.bmp", 0, MASK)
SFlame      = LoadAnimSprite("gfx/flame.bmp", 14, 10, 0, MASK)
SCloud      = LoadSprite("gfx/cloud.bmp", 0, MASK)
SBird       = LoadAnimSprite("gfx/bird.bmp", 50, 50, 0, MASK)
SGauge      = LoadSprite("gfx/gauge.bmp", 0, MASK)
STuft       = LoadSprite("gfx/tuft.bmp", 0, MASK)

-- Envelope centre inside the 44x52 balloon sprite.
ENV_CX, ENV_CY = 22, 17
BASKET_DROP = 33  -- envelope centre -> basket floor in balloon.bmp
-- Burner flame: 14x10 sprite anchored in the neck gap (sprite rows 33..42),
-- 16 px below the envelope centre rather than overlapping the envelope.
FLAME_DX, FLAME_DY = 7, 16
GAUGE_X, GAUGE_Y = 4, PLAY_TOP + 2

-- Physics / game balance (upgrade levels adjust these)
BALLOON_R     = 16
START_X       = 70
START_Y       = 105
FUEL_MAX      = 100
FUEL_START    = 60

-- Persistent upgrades (prefs namespace: game-balloon). Prices are sized so
-- one upgrade is affordable roughly every 5-10 therapy sessions (a session
-- banks ~8-15 coins at base ground speed); higher levels take longer.
-- There is deliberately no "easier blowing" upgrade: blowing IS the therapy.
DIST_PER_COIN    = 200  -- px of world travel per coin earned
PX_PER_M         = 10   -- px per displayed meter
SPEED_STEP       = 15   -- px/s steering speed per "Düse" level
DRIFT_STEP       = 12   -- px/s ground speed per "Düse" level
INSUL_IDLE_STEP  = 0.7  -- idle drain reduced per "Isolierung" level
INSUL_STEER_STEP = 1.5  -- steer drain reduced per "Isolierung" level
SPEED_PRICE      = { 80, 160, 320 }
INSUL_PRICE      = { 120, 240 }
SKIN_PRICE       = { 0, 80, 180, 350 }  -- index = skin, 0 = default

SPEED_LEVEL      = PrefsGetInt("speedLevel")
INSULATION_LEVEL = PrefsGetInt("insulationLevel")
SKINS_UNLOCKED   = PrefsGetInt("skinsUnlocked") | 1
SKIN             = Constrain(PrefsGetInt("skin"), 0, 3)
if ((SKINS_UNLOCKED >> SKIN) & 1) == 0 then SKIN = 0 end

MAX_SPEED     = 70 + SPEED_LEVEL * SPEED_STEP
DRIFT_SPEED   = 32 + SPEED_LEVEL * DRIFT_STEP  -- ground & obstacles, px/s
IDLE_DRAIN    = 2.0 - INSULATION_LEVEL * INSUL_IDLE_STEP
STEER_DRAIN   = 5.0 - INSULATION_LEVEL * INSUL_STEER_STEP
BLOW_GAIN     = 6.0  -- fuel/s while actively blowing (the flame is stoked)
FUEL_PER_BLOW = 40   -- a completed blow always adds this much fuel
HIT_COST      = 30   -- fuel lost per obstacle hit
CRASH_MS      = 2200 -- how long the balloon falls before the reset
SPAWN_MS      = 2200 -- obstacle spawn interval
GROUND_SPACING = 48  -- px between visible grass tufts

-- Mutable state (globals so it survives between scripts)
Fuel        = FUEL_START
GroundOffset = 0     -- px the world has scrolled this session
Distance    = 0      -- px flown this session (coins are banked per DIST_PER_COIN)
EarnedSaved = 0      -- coins already written to Prefs
BalloonX    = START_X
BalloonY    = START_Y
VelX        = 0
VelY        = 0
Obstacles   = {}     -- {x, y, r, kind}; kind 0 = cloud, 1 = bird
LastSpawnMs = 0
Crashes     = 0
State       = "flying"  -- flying | crashing
CrashMs     = 0
FlameUntilMs = 0

function SpawnObstacle()
  local r = 10 + math.random(0, 8)
  local y = PLAY_TOP + r + 8 + math.random(0, GROUND_Y - PLAY_TOP - 2 * (r + 8))
  table.insert(Obstacles, { x = 322 + r, y = y, r = r, kind = math.random(0, 1) })
end

-- Joystick axes or touch drag -> eased target velocity.
function UpdateSteering(Ms, MsDelta)
  local jx, jy = GetJoystickXY()
  if math.abs(jx) < 0.12 and math.abs(jy) < 0.12 then
    jx, jy = 0, 0
  end
  local tvx, tvy = jx * MAX_SPEED, jy * MAX_SPEED
  if IsTouchInZone(0, PLAY_TOP, 320, PLAY_BOTTOM - PLAY_TOP) then
    -- dragging steers toward the finger
    tvx = Constrain(GetTouchX() - BalloonX, -MAX_SPEED, MAX_SPEED)
    tvy = Constrain(GetTouchY() - BalloonY, -MAX_SPEED, MAX_SPEED)
  end
  local mag = math.min(math.sqrt(jx * jx + jy * jy), 1)
  if IsTouchInZone(0, PLAY_TOP, 320, PLAY_BOTTOM - PLAY_TOP) then
    mag = math.min(math.sqrt(tvx * tvx + tvy * tvy) / MAX_SPEED, 1)
  end
  local k = 1 - math.exp(-MsDelta / 180)  -- ~180 ms time constant
  VelX = VelX + (tvx - VelX) * k
  VelY = VelY + (tvy - VelY) * k
  return mag
end

function DrawCloud(x, y, r)
  local s = r / 10
  DrawSprite(SCloud, x, y, { scaleX = s, scaleY = s, flags = ALIGN_H_CENTER | ALIGN_V_CENTER })
end

function DrawBird(x, y, r)
  local s = r / 22  -- 50x50 gull from the plane game, scaled to the hit circle
  DrawSprite(SBird, x, y, {
    scaleX = s, scaleY = s,
    frame = (Ms // 250) % 2,
    flags = ALIGN_H_CENTER | ALIGN_V_CENTER,
  })
end

function DrawBalloon(Ms)
  local lit = CurrentlyBlowing or Ms < FlameUntilMs
  DrawSprite(State == "crashing" and SBalloonDead or BalloonSkin[SKIN + 1],
             BalloonX - ENV_CX, BalloonY - ENV_CY)
  if lit then
    DrawSprite(SFlame, BalloonX - FLAME_DX, BalloonY + FLAME_DY,
               { frame = (Ms // 180) % 2 })
  end
end

function DrawFuelGauge()
  DrawSprite(SGauge, GAUGE_X, GAUGE_Y)
  local h = (Fuel * 46) // FUEL_MAX
  FillRect(GAUGE_X + 3, GAUGE_Y + 49 - h, 16, h, Fuel < 35 and COL_FUEL_LOW or COL_FUEL_OK)
  SetTextColor(COL_WHITE)
  SetTextSize(1)
  DrawString("Tank", GAUGE_X, GAUGE_Y + 52)
end
